"""Basic regex matcher supporting '.' (any single char) and '*' (zero or more of preceding element)."""


def is_match(text: str, pattern: str) -> bool:
    """Return True if `pattern` matches the entire `text`."""

    def _match(ti: int, pi: int) -> bool:
        # Both consumed — success
        if pi == len(pattern):
            return ti == len(text)

        # Check if next pattern char is '*'
        star = pi + 1 < len(pattern) and pattern[pi + 1] == "*"

        if star:
            # Try consuming zero occurrences of pattern[pi], then one-or-more
            if _match(ti, pi + 2):
                return True
            while ti < len(text) and _char_match(text[ti], pattern[pi]):
                ti += 1
                if _match(ti, pi + 2):
                    return True
            return False
        else:
            # Single char match
            if ti < len(text) and _char_match(text[ti], pattern[pi]):
                return _match(ti + 1, pi + 1)
            return False

    def _char_match(c: str, p: str) -> bool:
        return p == "." or p == c

    return _match(0, 0)


# ── Tests ────────────────────────────────────────────────────────────────────

def test_dot_matches_single_char():
    assert is_match("a", ".")
    assert is_match("z", ".")
    assert not is_match("", ".")


def test_star_zero_occurrences():
    assert is_match("", "a*")
    assert is_match("", ".*")
    assert is_match("b", "a*b")  # zero 'a's then 'b'


def test_star_one_or_more():
    assert is_match("a", "a*")
    assert is_match("aaa", "a*")
    assert is_match("aaaa", ".*")


def test_star_with_dot():
    assert is_match("abc", ".*")
    assert is_match("", ".*")
    assert is_match("xyz", "a.*z")  # 'a' not at start → no match
    assert is_match("axyz", "a.*z")


def test_combined_dot_star():
    assert is_match("aab", "c*a*b")
    assert is_match("mississippi", "mis*is*p*.")
    assert not is_match("mississippi", "mis*is*p*i")
    assert is_match("mississippi", "mis*is*ip*i")


def test_exact_match():
    assert is_match("abc", "abc")
    assert not is_match("abcd", "abc")
    assert not is_match("ab", "abc")


def test_complex_patterns():
    assert is_match("aaa", "a*a")
    assert is_match("aaa", "ab*a*c*a")
    assert is_match("a", "ab*")
    assert not is_match("a", "ab*c")


def test_empty_text_and_pattern():
    assert is_match("", "")


def test_leading_star_requires_preceding():
    # '*' alone is invalid/meaningless; pattern must have preceding char
    # Our implementation treats bare '*' as literal (no preceding char to repeat)
    assert not is_match("a", "*")


